def run(_context):
    import adsk.core, adsk.cam
    app = adsk.core.Application.get()
    doc = app.activeDocument
    print("doc:", doc.name)
    prod = doc.products.itemByProductType('CAMProductType')
    cam = adsk.cam.CAM.cast(prod)
    print("setups:", [s.name for s in cam.setups])
    for s in cam.setups:
        print(" setup", s.name, "ops:", [o.name for o in s.allOperations])
        print(" machine:", s.machine.vendor if s.machine else None, s.machine.model if s.machine else None)
        print(" wcs?")
        try:
            print("  models:", [m.name for m in s.models])
        except Exception as e:
            print(e)
        try:
            print("  stock solids:", [b.name for b in s.stockSolids])
        except Exception as e:
            print(e)
    des = adsk.fusion.Design.cast(doc.products.itemByProductType('DesignProductType'))
    root = des.rootComponent
    for b in root.bRepBodies:
        bb = b.boundingBox
        print("body", b.name, bb.minPoint.asArray(), bb.maxPoint.asArray())
    for occ in root.allOccurrences:
        for b in occ.bRepBodies:
            bb=b.boundingBox
            print("occ body", occ.name, b.name, bb.minPoint.asArray(), bb.maxPoint.asArray())
    return "ok"

